\label{omega6rem}
\emph{Let $\omega:[0,+\infty)\rightarrow[0,+\infty)$ be nondecreasing and $\lim_{t\rightarrow+\infty}\omega(t)=+\infty$; i.e. $\omega$ is a weight function in the sense of \cite{genLegendreconj} (and of \cite{index}). Then the following are equivalent:}
\begin{itemize}
\item[$(a)$] \emph{$\omega$ satisfies \hyperlink{om6}{$(\omega_6)$}.}

\item[$(b)$] \emph{$\omega$ satisfies}
$$\exists\;a>1\;\exists\;H\ge 1\;\forall\;t\ge 0:\;\;\;a\omega(t)\le\omega(Ht)+H.$$

\item[$(c)$] \emph{$\omega$ satisfies}
$$\forall\;a>1\;\exists\;H\ge 1\;\forall\;t\ge 0:\;\;\;a\omega(t)\le\omega(Ht)+H.$$
\end{itemize}
\emph{$(a)\Rightarrow(b)$ and $(c)\Rightarrow(a)$ are clear (take $a:=2$). For $(b)\Rightarrow(c)$ let $b>1$ be arbitrary, then choose $n\in\mathbb{N}_{>0}$ such that $a^n\ge b$ with $a$ appearing in $(b)$, and iterate the estimate $n$-times.}

\label{gindexdef}
\emph{Let $\mathbf{M}\in\hyperlink{LCset}{\mathcal{LC}}$, then the \emph{moderate growth index} $g(\mathbf{M})$ is defined by}
$$g(\mathbf{M}):=\min\{d\in\mathbb{N}_{>0}:\;\;\;\eqref{genmg}\;\emph{is valid}\},$$
\emph{and let us set $g(\mathbf{M}):=+\infty$ if \eqref{genmg} is violated.}

\label{technlemma1}
Let $\omega\in\hyperlink{omset0}{\mathcal{W}_0}$ be given and $\mathcal{M}_{\omega}=\{\mathbf{W}^{(\ell)}: \ell>0\}$ the associated weight matrix. Then
\begin{equation}\label{technlemma1equ}
\forall\;x>0\;\forall\;c\in\mathbb{N}_{>0}:\;\;\;g(\mathbf{W}^{(cx)})\le g(\mathbf{W}^{(x)})\le 4g(\mathbf{W}^{(cx)}).
\end{equation}

\emph{Lemma \ref{technlemma1} holds, in particular, if $\omega=\omega_{\mathbf{M}}$ for some $\mathbf{M}\in\hyperlink{LCset}{\mathcal{LC}}$, and in this situation the conclusion follows for $\mathbf{M}=\mathbf{W}^{(1)}$; see \eqref{transformM}.}

\emph{Next note that \eqref{technlemma1equ} is equivalent to}
\begin{equation}\label{technlemma1equvar}
\forall\;y>0\;\forall\;d\in\mathbb{N}_{>0}:\;\;\;g(\mathbf{W}^{(y)})\le g(\mathbf{W}^{(y/d)})\le 4g(\mathbf{W}^{(y)}).
\end{equation}
\emph{Indeed, this equivalence holds by the correspondences $c=d$ and $y=xc$. On the other hand, \eqref{technlemma1equvar} can be shown directly analogously as \eqref{technlemma1equ} by involving \cite[$(4.10)$, $(5.2)$]{modgrowthstrange} and hence using the estimates}
\begin{equation*}\label{technlemma3equ1}
\forall\;x>0\;\forall\;c,p\in\mathbb{N}_{>0}:\;\;\;\vartheta^{(x/c)}_{c(p-1)}\le\vartheta^{(x)}_p=(\vartheta^{(x/c)}_{cp}\cdots\vartheta^{(x/c)}_{cp-c+1})^{1/c}\le\vartheta^{(x/c)}_{cp}.
\end{equation*}
\emph{Summarizing, if for some index $x_0>0$ one has that $\mathbf{W}^{(x_0)}$ satisfies \eqref{genmg} with some $d\in\mathbb{N}_{>0}$, then \eqref{genmg} also holds for any $\mathbf{W}^{(cx_0)}$ and $\mathbf{W}^{(x_0/c)}$ with a precise modification of the parameter $d$.}

\label{sequencematrixequivlemma}
Let $\mathbf{M},\mathbf{N}\in\hyperlink{LCset}{\mathcal{LC}}$ be given and consider the matrices $\mathcal{M}_{\omega_{\mathbf{M}}}=\{\mathbf{M}^{(x)}: x>0\}$ and $\mathcal{M}_{\omega_{\mathbf{N}}}=\{\mathbf{N}^{(x)}: x>0\}$. If $\mathbf{M}\hyperlink{preceq}{\preceq}\mathbf{N}$, then
$$\forall\;x\in\mathbb{N}_{>0}:\;\;\;\mathbf{M}^{(x)}\hyperlink{preceq}{\preceq}\mathbf{N}^{(x)},\hspace{15pt}\mathbf{M}^{(\frac{1}{2x})}\hyperlink{preceq}{\preceq}\mathbf{N}^{(\frac{1}{x})},$$
consequently $\mathcal{M}_{\omega_{\mathbf{M}}}\hyperlink{Mroumpreceq}{\{\preceq\}}\mathcal{M}_{\omega_{\mathbf{N}}}$ and $\mathcal{M}_{\omega_{\mathbf{M}}}\hyperlink{Mbeurpreceq}{(\preceq)}\mathcal{M}_{\omega_{\mathbf{N}}}$ is valid. More precisely, it holds that
\begin{equation}\label{sequencematrixequivlemmaequ}
\exists\;C\ge 1\;\forall\;x\in\mathbb{N}_{>0}\;\forall\;p\in\mathbb{N}:\;\;\;M^{(x)}_p\le C^pN^{(x)}_p,
\end{equation}
and
\begin{equation}\label{sequencematrixequivlemmaequ1}
\forall\;x\in\mathbb{N}_{>0}\;\exists\;C_x\ge 1\;\forall\;p\in\mathbb{N}:\;\;\;M^{(\frac{1}{2x})}_p\le C_x^pN^{(\frac{1}{x})}_p.
\end{equation}
Here, $C$ in \eqref{sequencematrixequivlemmaequ} can be chosen to be a constant such that $M_p\le C^pN_p$ holds for all $p\in\mathbb{N}$ and  in \eqref{sequencematrixequivlemmaequ1} set $C_x:=CM^{(\frac{1}{x})}_{2x}$.

\emph{Concerning Lemma \ref{sequencematrixequivlemma} we comment:}
\begin{itemize}
\item[$(*)$] \emph{In general, the converse implication in this result is unclear: $\mathcal{M}_{\omega_{\mathbf{M}}}\hyperlink{Mroumpreceq}{\{\preceq\}}\mathcal{M}_{\omega_{\mathbf{N}}}$ implies
	$$\exists\;C\ge 1\;\exists\;x\in\mathbb{N}_{>0}\;\forall\;p\in\mathbb{N}:\;\;\;M_p=M^{(1)}_p\le C^pN^{(x)}_p=C^p(N_{xp})^{\frac{1}{x}},$$
	and so $M_p^x\le C^{xp}N_{xp}$. Similarly, $\mathcal{M}_{\omega_{\mathbf{M}}}\hyperlink{Mbeurpreceq}{(\preceq)}\mathcal{M}_{\omega_{\mathbf{N}}}$ implies
	$$\exists\;C\ge 1\;\exists\;x\in\mathbb{N}_{>0}\;\forall\;p\in\mathbb{N}:\;\;\;M_p^x=(M^{(1)}_p)^x=M^{(\frac{1}{x})}_{xp}\le C^{xp}N^{(1)}_{xp}=C^{xp}N_{xp}.$$
	Thus, in order to verify $\mathbf{M}\hyperlink{preceq}{\preceq}\mathbf{N}$, either $\mathbf{M}$ or $\mathbf{N}$ is required to satisfy moderate growth; see the proof of \cite[Thm. 4.4, $(iii)\Rightarrow(ii)$]{orliczpaper}.}

\item[$(*)$] \emph{Lemma \ref{sequencematrixequivlemma} strengthens one part of the conclusions in \cite[Lemma 4.9 $(i)$]{modgrowthstrange}: There it has been shown that for equivalent sequences $\mathbf{M},\mathbf{N}\in\hyperlink{LCset}{\mathcal{LC}}$ under the assumption that (at least one) sequence is \emph{strongly nonquasianalytic,} see (M.3) in \cite{Komatsu73} and e.g. $(\beta_1)$, $(\gamma_1)$ on \cite[p. 5]{modgrowthstrange}, we have both R- and B-equivalence between the associated weight matrices. Lemma \ref{sequencematrixequivlemma} shows that this assumption and the arguments involving \eqref{assostrongnq} are superfluous.}

\emph{However, in \cite[Lemma 4.9 $(i)$]{modgrowthstrange} even $\omega_{\mathbf{M}}\hyperlink{sim}{\sim}\omega_{\mathbf{N}}$ was shown and which implies stronger estimates than \eqref{sequencematrixequivlemmaequ} and \eqref{sequencematrixequivlemmaequ1}: the exponential growth factors (in the variable $p$) can be replaced by a constant; see also e.g. \eqref{mainmgthm3equ2}.}
\end{itemize}

\label{technlemma2}
Let $\mathbf{M},\mathbf{L}\in\hyperlink{LCset}{\mathcal{LC}}$ be given. Then the following are equivalent:
\begin{itemize}
\item[$(i)$] It holds that
\begin{equation}\label{technlemma1equ0}
\exists\;a\in\mathbb{N}_{>0}\;\exists\;B\ge 1\;\forall\;t\ge 0:\;\;\;\omega_{\mathbf{L}\star\widetilde{\mathbf{M}}^a}(t)=\omega_{\mathbf{L}}(t)+\omega_{\widetilde{\mathbf{M}}^a}(t)\le\omega_{\mathbf{L}}(Bt)+B.
\end{equation}

\item[$(ii)$] It holds that
\begin{equation}\label{technlemma1equ2}
\exists\;a\in\mathbb{N}_{>0}\;\exists\;C\ge 1\;\forall\;t\ge 0:\;\;\;\omega_{\mathbf{M}}(t)\le a(\omega_{\mathbf{L}}(Ct)-\omega_{\mathbf{L}}(t))+C.
\end{equation}

\item[$(iii)$] It holds that
$$\exists\;a\in\mathbb{N}_{>0}:\;\;\mathbf{L}\hyperlink{preceq}{\preceq}\mathbf{L}\star\widetilde{\mathbf{M}}^a;$$
i.e. in view of \eqref{tildeweightsequences} and \eqref{convolvesequ},
\begin{equation}\label{technlemma1equ1}
\exists\;a\in\mathbb{N}_{>0}\;\exists\;H\ge 1\;\forall\;p\in\mathbb{N}\;\forall\;0\le q\le p:\;\;\;L_p\le H^pL_q\widetilde{M}^a_{p-q}=H^pL_q(M_{a(p-q)})^{\frac{1}{a}}.
\end{equation}
\end{itemize}
Concerning the parameter $a$, the proof shows the following correspondences: In $(i)$ and $(iii)$ we can take the same $a$; if $(i)$ holds with $a$ then $(ii)$ with $2a$ and if $(ii)$ holds with $a$ then also $(i)$.

\label{technlemma2cor}
Let $\mathbf{M}\in\hyperlink{LCset}{\mathcal{LC}}$ be given. Then the following are equivalent:
\begin{itemize}
\item[$(i)$] $\omega_{\mathbf{M}}$ satisfies \eqref{technlemma1equ2} for $\mathbf{M}=\mathbf{L}$,

\item[$(ii)$] $\omega_{\mathbf{M}}$ satisfies \hyperlink{om6}{$(\omega_6)$},

\item[$(iii)$] $\mathbf{M}$ satisfies \hyperlink{mg}{$(\operatorname{mg})$}.
\end{itemize}

\label{technlemma3}
Let $\mathbf{M},\mathbf{L}\in\mathbb{R}_{>0}^{\mathbb{N}}$ be given such that $M_0=1=L_0$ and such that $\mathbf{L}$ is log-convex. Recall also the notation $\lambda_p:=\frac{L_p}{L_{p-1}}$, $p\in\mathbb{N}_{>0}$ and $\lambda_0:=1$. Then the following are equivalent:
\begin{itemize}
\item[$(i)$] It holds that
\begin{equation}\label{technlemma2equ}
\exists\;a\in\mathbb{N}_{>0}\;\exists\;B\ge 1\;\forall\;p\in\mathbb{N}:\;\;\;L_{2p}\le B^pL_p\widetilde{M}^a_p.
\end{equation}

\item[$(ii)$] It holds that
\begin{equation}\label{technlemma1equ1weak}
\exists\;a\in\mathbb{N}_{>0}\;\exists\;H\ge 1\;\forall\;p,q\in\mathbb{N},\;0\le q\le p:\;\;\;L_{p+q}\le H^pL_q\widetilde{M}^a_{p}.
\end{equation}

\item[$(iii)$] It holds that
\begin{equation}\label{crucialcompequmix}
\exists\;a\in\mathbb{N}_{>0}\;\exists\;A\ge 1\;\forall\;p\in\mathbb{N}_{>0}:\;\;\;\lambda_p\le A(M_{ap})^{\frac{1}{ap}}=A(\widetilde{M}^a_{p})^{\frac{1}{p}};
\end{equation}
i.e. the mixed variant of \eqref{genmg} between $\mathbf{L}$ and $\mathbf{M}$ resp. the mixed variant of \eqref{mgstrange} between $\mathbf{L}$ and $\widetilde{\mathbf{M}}^a$.
\end{itemize}
Concerning the parameter $a\in\mathbb{N}_{>0}$ the proof shows the following correspondences: In $(i)$ and $(ii)$ one can choose the same $a$; if $(i)$ holds with $a$ then also $(iii)$; if $(iii)$ is valid for $a$ then $(ii)$ with $2a$.

\label{technlemma23cor}
Let $\mathbf{M},\mathbf{L}\in\hyperlink{LCset}{\mathcal{LC}}$ be given.
\begin{itemize}
\item[$(i)$] Any of the equivalent assertions in Proposition \ref{technlemma2} implies the equivalent assertions listed in Proposition \ref{technlemma3} and the proof shows that if \eqref{technlemma1equ1} holds with some $a$, then \eqref{technlemma2equ} as well.

\item[$(ii)$] When $\mathbf{M}=\mathbf{L}$, then the converse of $(i)$ is not valid in general; in particular the \emph{q-Gevrey sequences} $M_p:=q^{p^2}$, $q>1$, provide a (counter-)example.
\end{itemize}

\label{weakseprem}
\emph{\eqref{technlemma1equ1} and \eqref{technlemma1equ1weak} should be compared with the ``weak separativity condition'' (W.S.) in \cite[p. 669]{matsumoto} between the sequences $\mathbf{L}$ and $\widetilde{\mathbf{M}}^a$. Indeed, for given $\mathbf{L}\in\mathbb{R}_{>0}^{\mathbb{N}}$ this condition reads as follows:}
\begin{equation}\label{weaksep}
\exists\;A>0\;\exists\;\mathbf{M}\in\mathbb{R}_{>0}^{\mathbb{N}}\;\forall\;p,q\in\mathbb{N}:\;\;\;L_{p+q}\le A^pL_pM_q.
\end{equation}
\emph{\eqref{weaksep} for the particular choice $\mathbf{M}=\widetilde{\mathbf{M}}^a$ obviously implies both \eqref{technlemma1equ1} and \eqref{technlemma2equ}. If $\mathbf{L}$ is log-convex, then \eqref{weaksep} gives $\lambda_p^p\le\lambda_{p+1}\cdots\lambda_{2p}=\frac{L_{2p}}{L_p}\le A^pM_p$ and so $\lambda_p\le A(M_p)^{1/p}$ for all $p\in\mathbb{N}_{>0}$; i.e. the mixed variant of \eqref{mgstrange} resp. \eqref{genmg} between $\mathbf{L}$ and $\mathbf{M}$.}

\label{technlemma4}
Let $\mathbf{M}$ be a given log-convex sequence such that $M_0=1$ and satisfying \eqref{genmg} for some $d\in\mathbb{N}_{>0}$. Then any log-convex sequence $\mathbf{N}$ being equivalent to $\mathbf{M}$ (and with $N_0=1$) has \eqref{genmg} too; i.e. \eqref{genmg} is preserved under equivalence of log-convex sequences.

Indeed, if $\mathbf{M}$ satisfies \eqref{genmg} with $d$, then for any equivalent log-convex $\mathbf{N}$ we can choose $2d$.

\label{step1}
Let $\mathbf{M},\mathbf{N}\in\hyperlink{LCset}{\mathcal{LC}}$ be given, then the following are equivalent:
\begin{itemize}
\item[$(i)$] It holds that
\begin{equation}\label{auxiweightfct1}
\exists\;C\ge 0\;\exists\;B\ge 1\;\exists\;\ell>0\;\forall\;t\ge 0:\;\;\;2\ell\omega_{\mathbf{N}}(t)\le\omega_{\mathbf{M}}((Bt)^{\ell})+C.
\end{equation}
\item[$(ii)$] It holds that
\begin{equation}\label{auxiweightfct2}
\exists\;A,A_1\ge 1\;\exists\;\ell>0\;\forall\;p\in\mathbb{N}:\;\;\;M_{2p}\le A_1A^{2p\ell}N_p^{2\ell}.
\end{equation}
\end{itemize}
The parameter $\ell$ can be chosen to be the same in \eqref{auxiweightfct1} and \eqref{auxiweightfct2}; moreover we have the correspondences $A_1=e^C$ and $B=A$.

\label{multthm}
Let $\mathbf{M},\mathbf{N}\in\hyperlink{LCset}{\mathcal{LC}}$ be given, then
\begin{equation}\label{multthmequ}
\forall\;t\ge 0:\;\;\;\omega_{\mathbf{M}\mathbf{N}}(t)=\omega_{\mathbf{M}}\check{\star}\omega_{\mathbf{N}}(t),
\end{equation}
with
\begin{equation}\label{uppertransformgen}
\sigma\check{\star}\tau(t):=\inf_{s>0}\{\sigma(s)+\tau(t/s)\},\;\;\;t\in[0,+\infty).
\end{equation}

\label{upptrafothm}
Let $\mathbf{M},\mathbf{N},\mathbf{L}\in\hyperlink{LCset}{\mathcal{LC}}$ be given, then the following are equivalent:
\begin{itemize}
\item[$(i)$] It holds that
\begin{equation}\label{technlemma2equsuper}
\exists\;a\in\mathbb{N}_{>0}\;\exists\;B\ge 1\;\forall\;p\in\mathbb{N}:\;\;\;L_{2p}\le B^pN_p\widetilde{M}^a_p.
\end{equation}
\item[$(ii)$] It holds that
\begin{equation}\label{technlemma2equsuperfct}
\exists\;a\in\mathbb{N}_{>0}\;\exists\;A\ge 1\;\exists\;C\ge 0\;\forall\;t\ge 0:\;\;\;\omega_{\mathbf{N}\widetilde{\mathbf{M}}^a}(t^2)=\omega_{\mathbf{N}}\check{\star}\omega_{\widetilde{\mathbf{M}}^a}(t^2)\le\omega_{\mathbf{L}}(At)+C.
\end{equation}
\end{itemize}
The proof shows that we can take in both estimates the same parameter $a$ and note that when \eqref{technlemma2equsuperfct} holds with some $a$, then also for all $a'\ge a$.

\label{omegaMcharacterzing1}
Let $\mathbf{M}\in\hyperlink{LCset}{\mathcal{LC}}$ be given, then the following are equivalent:
\begin{itemize}
\item[$(i)$] $\mathbf{M}$ satisfies \eqref{genmg}.

\item[$(ii)$] The associated weight function satisfies
\begin{equation}\label{omegaMgenmg}
\exists\;a\in\mathbb{N}_{>0}\;\exists\;A\ge 1\;\exists\;C\ge 0\;\forall\;t\ge 0:\;\;\;\omega_{\mathbf{M}\widetilde{\mathbf{M}}^a}(t^2)=\omega_{\mathbf{M}}\check{\star}\omega_{\widetilde{\mathbf{M}}^a}(t^2)\le\omega_{\mathbf{M}}(At)+C.
\end{equation}
\end{itemize}
If \eqref{genmg} holds with some $d\in\mathbb{N}_{>0}$, then choose $a:=2d$ in \eqref{omegaMgenmg}; if \eqref{omegaMgenmg} is valid for some $a\in\mathbb{N}_{>0}$, then choose $d:=a$ in \eqref{genmg}.

\label{omegaMcharacterzing1rem}
\emph{If \eqref{omegaMgenmg} holds with $a=1$, then $\mathbf{M}^a=\mathbf{M}$ and by \eqref{powersub} this estimate gives}
$$\exists\;A\ge 1\;\exists\;C\ge 0\;\forall\;t\ge 0:\;\;\;2\omega_{\mathbf{M}}(t)=\omega_{\mathbf{M}\mathbf{M}}(t^2)\le\omega_{\mathbf{M}}(At)+C;$$
\emph{i.e. \hyperlink{om6}{$(\omega_6)$} for $\omega_{\mathbf{M}}$. And by the known characterization $\mathbf{M}$ satisfies \eqref{genmg} with $d=1$. Indeed, in view of \eqref{powersub} condition \hyperlink{om6}{$(\omega_6)$} is precisely \eqref{omegaMgenmg} with $a=1$.}

\label{upptrafothmcor}
Let $\mathbf{M},\mathbf{N},\mathbf{L}\in\hyperlink{LCset}{\mathcal{LC}}$ be given.
\begin{itemize}
\item[$(i)$] If one has
\begin{equation}\label{technlemma2equsuperfctsuf}
\exists\;A\ge 1\;\exists\;C\ge 0\;\forall\;t\ge 0:\;\;\;\omega_{\mathbf{M}\mathbf{N}}(t^2)=\omega_{\mathbf{N}}\check{\star}\omega_{\mathbf{M}}(t^2)\le\omega_{\mathbf{L}}(At)+C,
\end{equation}
then \eqref{technlemma2equsuperfct} holds for any $a\in\mathbb{N}_{>0}$ with the same parameters $A,C$.

\item[$(ii)$] If \eqref{technlemma2equsuperfct} holds, then
\begin{equation}\label{technlemma2equsuperfctnec}
\exists\;a\in\mathbb{N}_{>0}\;\exists\;A\ge 1\;\exists\;B\ge 0\;\forall\;t\ge 0:\;\;\;\omega_{\mathbf{M}\mathbf{N}}(t^2)=\omega_{\mathbf{N}}\check{\star}\omega_{\mathbf{M}}(t^2)\le a\omega_{\mathbf{L}}(At)+B.
\end{equation}
Indeed, if \eqref{technlemma2equsuperfct} is valid with some $a$, then in \eqref{technlemma2equsuperfctnec} it suffices to choose $2a$.
\end{itemize}

\emph{The previous result should be compared with the following comment: When $\mathbf{M}$, $\mathbf{N}$ are log-convex and normalized then
$$\forall\;a\in\mathbb{N}_{>0}:\;\;\;\mathbf{N}\mathbf{M}\le\mathbf{N}\widetilde{\mathbf{M}}^a\le\widetilde{\mathbf{N}}^a\widetilde{\mathbf{M}}^a,$$
see Section \ref{auxsection}, and consequently the definition of the associated function gives
$$\forall\;t\ge 0:\;\;\;\omega_{\widetilde{\mathbf{M}}^a\widetilde{\mathbf{N}}^a}(t)\le\omega_{\mathbf{N}\widetilde{\mathbf{M}}^a}(t)\le\omega_{\mathbf{N}\mathbf{M}}(t).$$}
\emph{In view of Corollaries \ref{omegaMcharacterzing} and \ref{omegaMcharacterzing1} and $(i)$ in Lemma \ref{upptrafothmcor} a sufficient condition for having \eqref{crucialcompequmix} is}
$$\exists\;A\ge 1\;\exists\;B\ge 0\;\forall\;t\ge 0:\;\;\;\omega_{\mathbf{L}\mathbf{M}}(t^2)=\omega_{\mathbf{L}}\check{\star}\omega_{\mathbf{M}}(t^2)\le\omega_{\mathbf{L}}(At)+B,$$
\emph{and a sufficient condition for having \eqref{genmg} is}
$$\exists\;A\ge 1\;\exists\;B\ge 0\;\forall\;t\ge 0:\;\;\;\omega_{\mathbf{M}^2}(t^2)=\omega_{\mathbf{M}}\check{\star}\omega_{\mathbf{M}}(t^2)\le\omega_{\mathbf{M}}(At)+B.$$
\emph{By taking into account \eqref{powersub} this property turns out to be \hyperlink{om6}{$(\omega_6)$} and hence this is consistent with the known characterization.}

\label{omegaMcharacterzing2}
Let $\omega\in\hyperlink{omset0}{\mathcal{W}_0}$ be given and let $\mathcal{M}_{\omega}=\{\mathbf{W}^{(\ell)}: \ell>0\}$ be the associated weight matrix. Then the following are equivalent:
\begin{itemize}
\item[$(i)$] \eqref{omegagenmg} is valid.

\item[$(ii)$] $\mathcal{M}_{\omega}$ satisfies \eqref{rstrange} and/or \eqref{bstrange}.
\end{itemize}

\emph{Let $\omega$ be nondecreasing and satisfying $\lim_{t\rightarrow+\infty}\omega(t)=+\infty$, i.e. $\omega$ is a weight function in the sense of \cite{genLegendreconj} (and of \cite{index}), then we immediately get that \hyperlink{om6}{$(\omega_6)$} for $\omega$ implies:}
$$2\omega\check{\star}\omega(t)=\inf_{s>0}\{2\omega(s)+2\omega(t/s)\}\le\inf_{s>0}\{\omega(Hs)+\omega(Ht/s)\}+2H=\omega\check{\star}\omega(H^2t)+2H.$$
\emph{Note that this implication also holds by \cite[Rem. 2.3, Thm. 3.4 $(ii)$]{genLegendreconj} where the growth index $\overline{\gamma}(\omega)$ from \cite[Sect. 2.4]{genLegendreconj} is involved in the arguments. However, in general the converse implication is not clear and note that for the arguments in Lemma \ref{om6newcharacterization} crucially \eqref{goodequivalenceclassic} is used and for this, more precisely for the second estimate there, the convexity condition \hyperlink{om4}{$(\omega_4)$} is required.}

\label{om1newcharacterization}
Let $\omega\in\hyperlink{omset0}{\mathcal{W}_0}$ be given. Then $\omega$ satisfies \hyperlink{om1}{$(\omega_1)$} if and only if
$$\exists\;L\ge 1\;\exists\;C\ge 0\;\forall\;t\ge 0:\;\;\;\omega\check{\star}\omega((2t)^2)\le L\omega(t)+C.$$

\label{mainmgthm3}
Let $\sigma\in\hyperlink{omset0}{\mathcal{W}_0}$ be given with associated weight matrix $\mathcal{M}_{\sigma}=\{\mathbf{S}^{(\ell)}: \ell>0\}$.
\begin{itemize}
\item[$(i)$] Assume that there exists a weight matrix $\mathcal{N}=\{\mathbf{N}^{(x)}: x\in\mathcal{I}\}$ such that $\mathcal{M}_{\sigma}\{\approx\}\mathcal{N}$ and such that

\item[$(ii)$] $\mathcal{N}$ satisfies the quotient-root comparison property of Roumieu type \eqref{rstrange}.
\end{itemize}
Then $\mathbf{S}^{(1)}$ has to satisfy
\begin{equation}\label{mainmgthm3equ}
\exists\;\ell\in\mathbb{N}_{>0}\;\exists\;B,B_1\ge 1\;\forall\;p\in\mathbb{N}_{>0}:\;\;\;\frac{S^{(1)}_{p}}{(S^{(1)}_{\ell(p-1)})^{\frac{1}{\ell}}}\le BB_1^p(S^{(1)}_{\ell p})^{\frac{1}{\ell p}}.
\end{equation}
If one assumes instead that $\mathcal{M}_{\sigma}(\approx)\mathcal{N}$ and such that $\mathcal{N}$ satisfies the quotient-root comparison property of Beurling-type \eqref{bstrange}, then $\mathbf{S}^{(1)}$ has to satisfy
\begin{equation}\label{mainmgthm3equ1}
\exists\;\ell\in\mathbb{N}_{>0}\;\exists\;B,B_1\ge 1\;\forall\;p\in\mathbb{N}_{>0}:\;\;\;\frac{(S^{(1)}_p)^{\ell}}{S^{(1)}_{\ell p-1}}\le BB_1^{p}(S^{(1)}_{\ell p})^{\frac{1}{\ell p}}.
\end{equation}
